export type SteeringRequesterSessionKey = string;

export type SteeringCompletionStatus =
  | "pending"
  | "suspended"
  | "in_progress"
  | "delivered"
  | "discarded"
  | "failed"
  | "cancelled";

export type SteeringLeaseId = string;

export interface SteeringCompletionResult {
  prompt?: string;
  content?: string;
  output?: string;
  result?: string;
  [key: string]: unknown;
}

export interface SteeringCompletionItem {
  id: string;
  requesterSessionKey: SteeringRequesterSessionKey;
  requestId?: string;
  status: SteeringCompletionStatus;
  result?: SteeringCompletionResult;
  prompt?: string;
  steeringLeaseId?: SteeringLeaseId;
  leasedAt?: number;
  createdAt?: number;
  updatedAt?: number;
}

export interface SteeringLease {
  leaseId: SteeringLeaseId;
  itemId: string;
  requesterSessionKey: SteeringRequesterSessionKey;
  requestId?: string;
  prompt: string;
  leasedAt: number;
}

export interface SteeringQueueOptions {
  /** Items which were already present in the queue. */
  items?: SteeringCompletionItem[];
  /** A stale lease is eligible for takeover after this many milliseconds. */
  staleLeaseMs?: number;
  /** Optional clock, primarily useful for deterministic hosts and tests. */
  now?: () => number;
}

const DEFAULT_STALE_LEASE_MS = 5 * 60 * 1000;

function isLeaseableStatus(status: SteeringCompletionStatus): boolean {
  return status === "pending" || status === "suspended";
}

function isTerminalStatus(status: SteeringCompletionStatus): boolean {
  return !isLeaseableStatus(status) && status !== "in_progress";
}

function textResult(result: SteeringCompletionResult | undefined): string {
  if (!result) {
    return "";
  }
  const candidates = [result.prompt, result.content, result.output, result.result];
  return candidates.find((value): value is string => typeof value === "string" && value.length > 0) ?? "";
}

/**
 * Build the prompt injected into a run. The completion result is retained in
 * the merged prompt so a lease cannot silently lose the useful part of a
 * completion.
 */
export function buildMergedSteeringPrompt(
  item: Pick<SteeringCompletionItem, "id" | "prompt" | "result">,
): string {
  const result = textResult(item.result);
  const base = item.prompt?.trim() ?? "";
  if (!result) {
    return base;
  }
  if (!base) {
    return result;
  }
  return `${base}\n\n[steering completion ${item.id}]\n${result}`;
}

/**
 * In-memory queue for completed steering work.
 *
 * A lease is the capability to inject one completion into one run. It is
 * bound to both the item and requester session. Acknowledgements are
 * monotonic: only the currently matching lease can complete an item, and a
 * repeated acknowledgement is deliberately a no-op.
 */
export class AgentSteeringQueue {
  private readonly items = new Map<string, SteeringCompletionItem>();
  private readonly staleLeaseMs: number;
  private readonly now: () => number;
  private leaseSequence = 0;

  constructor(options: SteeringQueueOptions = {}) {
    this.staleLeaseMs = options.staleLeaseMs ?? DEFAULT_STALE_LEASE_MS;
    this.now = options.now ?? Date.now;
    for (const item of options.items ?? []) {
      this.items.set(item.id, { ...item });
    }
  }

  /** Add or replace a completion without granting it a lease. */
  enqueue(item: SteeringCompletionItem): SteeringCompletionItem {
    const current = this.items.get(item.id);
    if (current?.steeringLeaseId) {
      throw new Error(`Steering completion ${item.id} is already leased`);
    }
    const next: SteeringCompletionItem = {
      ...item,
      createdAt: item.createdAt ?? current?.createdAt ?? this.now(),
      updatedAt: this.now(),
    };
    this.items.set(next.id, next);
    return { ...next };
  }

  enqueueCompletion(item: SteeringCompletionItem): SteeringCompletionItem {
    return this.enqueue(item);
  }

  complete(item: SteeringCompletionItem): SteeringCompletionItem {
    return this.enqueue({ ...item, status: "pending" });
  }

  get(id: string): SteeringCompletionItem | undefined {
    const item = this.items.get(id);
    return item ? { ...item } : undefined;
  }

  list(requesterSessionKey?: SteeringRequesterSessionKey): SteeringCompletionItem[] {
    const result = [...this.items.values()]
      .filter((item) => requesterSessionKey === undefined || item.requesterSessionKey === requesterSessionKey)
      .filter((item) => isLeaseableStatus(item.status))
      .map((item) => ({ ...item }));
    return result;
  }

  listPending(requesterSessionKey?: SteeringRequesterSessionKey): SteeringCompletionItem[] {
    return this.list(requesterSessionKey);
  }

  private isStale(item: SteeringCompletionItem, at: number): boolean {
    return (
      item.status === "in_progress" &&
      typeof item.leasedAt === "number" &&
      at - item.leasedAt > this.staleLeaseMs
    );
  }

  /**
   * Lease the oldest available completion for a requester session. A stale
   * in-progress lease can be taken over; taking it over invalidates the old
   * lease because the item receives a new lease id.
   */
  lease(
    requesterSessionKey: SteeringRequesterSessionKey,
    requestId?: string,
  ): SteeringLease | null {
    const at = this.now();
    const candidates = [...this.items.values()]
      .filter((item) => item.requesterSessionKey === requesterSessionKey)
      .filter((item) => requestId === undefined || item.requestId === undefined || item.requestId === requestId)
      .filter((item) => isLeaseableStatus(item.status) || this.isStale(item, at))
      .sort((left, right) => {
        const leftTime = left.leasedAt ?? left.createdAt ?? 0;
        const rightTime = right.leasedAt ?? right.createdAt ?? 0;
        return leftTime - rightTime || left.id.localeCompare(right.id);
      });

    const item = candidates[0];
    if (!item) {
      return null;
    }

    const leaseId = `steering-lease-${at}-${++this.leaseSequence}`;
    item.status = "in_progress";
    item.steeringLeaseId = leaseId;
    item.leasedAt = at;
    item.updatedAt = at;

    return {
      leaseId,
      itemId: item.id,
      requesterSessionKey: item.requesterSessionKey,
      requestId: item.requestId,
      prompt: buildMergedSteeringPrompt(item),
      leasedAt: at,
    };
  }

  /** Acknowledge successful delivery of a leased completion. */
  ack(leaseId: SteeringLeaseId, requesterSessionKey?: SteeringRequesterSessionKey): boolean {
    const item = this.findByLease(leaseId, requesterSessionKey);
    if (!item || item.status !== "in_progress" || item.steeringLeaseId !== leaseId) {
      return false;
    }

    const at = this.now();
    item.status = "delivered";
    item.steeringLeaseId = undefined;
    item.leasedAt = undefined;
    item.updatedAt = at;
    return true;
  }

  acknowledge(leaseId: SteeringLeaseId, requesterSessionKey?: SteeringRequesterSessionKey): boolean {
    return this.ack(leaseId, requesterSessionKey);
  }

  /**
   * Release a failed lease. The completion becomes pending and may be leased
   * exactly once by the next lease operation. The released capability cannot
   * subsequently acknowledge the item.
   */
  release(leaseId: SteeringLeaseId, requesterSessionKey?: SteeringRequesterSessionKey): boolean {
    const item = this.findByLease(leaseId, requesterSessionKey);
    if (!item || item.status !== "in_progress" || item.steeringLeaseId !== leaseId) {
      return false;
    }

    const at = this.now();
    item.status = "pending";
    item.steeringLeaseId = undefined;
    item.leasedAt = undefined;
    item.updatedAt = at;
    return true;
  }

  /** Mark a completion as no longer eligible for injection. */
  cancel(id: string): boolean {
    return this.setTerminalStatus(id, "cancelled");
  }

  discard(id: string): boolean {
    return this.setTerminalStatus(id, "discarded");
  }

  fail(id: string): boolean {
    return this.setTerminalStatus(id, "failed");
  }

  terminate(id: string): boolean {
    return this.cancel(id);
  }

  private setTerminalStatus(id: string, status: "cancelled" | "discarded" | "failed"): boolean {
    const item = this.items.get(id);
    if (!item || isTerminalStatus(item.status)) {
      return false;
    }
    item.status = status;
    item.steeringLeaseId = undefined;
    item.leasedAt = undefined;
    item.updatedAt = this.now();
    return true;
  }

  private findByLease(
    leaseId: SteeringLeaseId,
    requesterSessionKey?: SteeringRequesterSessionKey,
  ): SteeringCompletionItem | undefined {
    return [...this.items.values()].find(
      (item) =>
        item.steeringLeaseId === leaseId &&
        (requesterSessionKey === undefined || item.requesterSessionKey === requesterSessionKey),
    );
  }
}

export const DEFAULT_STEERING_STALE_LEASE_MS = DEFAULT_STALE_LEASE_MS;

export function createAgentSteeringQueue(options: SteeringQueueOptions = {}): AgentSteeringQueue {
  return new AgentSteeringQueue(options);
}

